style.css:
@-moz-document domain("pinterest.com") {
html {
  background-color: #0a0a0a !important;
  background-image:
    linear-gradient(to right, rgba(130,255,167,.13) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(130,255,167,.13) 1px, transparent 1px),
    repeating-linear-gradient(to bottom,
      rgba(10,10,10,0) 0px, rgba(10,10,10,0) 3px,
      rgba(105,255,153,.035) 3px, rgba(105,255,153,.035) 4px) !important;
  background-size: 40px 40px, 40px 40px, 100% 4px !important;
  background-position: 0 0 !important;
  background-repeat: repeat !important;
  background-attachment: fixed !important;
}

body, #__PWS_ROOT__, #__PWS_ROOT__ > div,
[data-test-id="app"], [data-test-id="app-content"], main,
[role="main"], [data-test-id="homefeed"],
[data-test-id="search-page"], [data-test-id="board-feed"],
[data-test-id="profile-page"], [data-test-id="profile-boards-feed"],
[data-test-id="pin-grid"], [data-test-id="grid"],
[data-test-id="masonry-container"] {
  background-color: transparent !important;
  color: #d9ffe6 !important;
}

html, body, button, input, textarea, select,
[contenteditable="true"], [role="textbox"],
h1, h2, h3, h4, h5, h6, p, a, label, legend,
[class*="Text__"], [class*="Heading__"] {
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  font-variant-ligatures: none !important;
}

body {
  accent-color: #00ff66 !important;
}

h1, h2, h3, h4, h5, h6, p, label, legend {
  color: #d9ffe6 !important;
}

a {
  color: #7fffac !important;
}

a:hover {
  color: #b7ffce !important;
}

small, time, [data-test-id="pin-description"],
[data-test-id="pin-attribution"], [data-test-id="board-description"] {
  color: #9ee5b6 !important;
}

::selection {
