}

nav a:hover, [role="navigation"] a:hover,
[aria-current="page"], [role="tab"][aria-selected="true"] {
  background-color: rgba(12,91,39,.56) !important;
  color: #d9ffe6 !important;
  box-shadow: inset 0 -2px #00ff66 !important;
}

[data-test-id="pinterest-logo"] svg,
a[href="/"] svg[aria-label*="Pinterest"],
svg[aria-label="Pinterest"], svg[aria-label="Pinterest logo"] {
